def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of recency (most recent at end)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Remove expired entries
            cache = {k: v for k, v in cache.items() if v[1] + ttl > t}
            lru_order = [k for k in lru_order if k in cache]

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)
            else:
                # Key is new - check if we need to evict
                if len(cache) >= capacity:
                    # Evict least recently used
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

            # Add the new entry
            cache[key] = (value, t)
            lru_order.append(key)

        elif op[0] == 'get':
            _, t, key = op

            # Remove expired entries
            cache = {k: v for k, v in cache.items() if v[1] + ttl > t}
            lru_order = [k for k in lru_order if k in cache]

            # Check if key exists and is not expired
            if key in cache:
                # Move to most recently used
                lru_order.remove(key)
                lru_order.append(key)
                results.append(cache[key][0])
            else:
                results.append(-1)

    return results

